package com.example.starter.firmware.repo;

import com.example.starter.firmware.domain.ManifestChunk;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

/**
 * 发布版本分片清单数据访问。一个发布单至多一份清单；一经有任务拉取即不可修改（由服务层在行锁内裁决）。
 */
@Repository
public class ManifestRepository {

    /**
     * 清单概要。
     *
     * @param releaseId        所属发布单ID
     * @param chunkCount       分片总数
     * @param aggregateDigest  完整包聚合摘要
     * @param registeredAtUtc  登记时刻（UTC ISO-8601）
     */
    public record ManifestRow(long releaseId, int chunkCount, String aggregateDigest,
                              String registeredAtUtc) {
    }

    private final JdbcTemplate jdbc;

    public ManifestRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void insertManifest(long releaseId, int chunkCount, String aggregateDigest, String registeredAtUtc) {
        jdbc.update("INSERT INTO release_manifest (release_id, chunk_count, aggregate_digest, registered_at_utc)"
                + " VALUES (?, ?, ?, ?)", releaseId, chunkCount, aggregateDigest, registeredAtUtc);
    }

    public void deleteManifest(long releaseId) {
        jdbc.update("DELETE FROM release_manifest_chunk WHERE release_id = ?", releaseId);
        jdbc.update("DELETE FROM release_manifest WHERE release_id = ?", releaseId);
    }

    public void insertChunk(long releaseId, int chunkIndex, String digest) {
        jdbc.update("INSERT INTO release_manifest_chunk (release_id, chunk_index, digest) VALUES (?, ?, ?)",
                releaseId, chunkIndex, digest);
    }

    public Optional<ManifestRow> findManifest(long releaseId) {
        return jdbc.query("SELECT release_id, chunk_count, aggregate_digest, registered_at_utc"
                        + " FROM release_manifest WHERE release_id = ?",
                (rs, rowNum) -> new ManifestRow(rs.getLong("release_id"), rs.getInt("chunk_count"),
                        rs.getString("aggregate_digest"), rs.getString("registered_at_utc")),
                releaseId).stream().findFirst();
    }

    /**
     * 按序号升序（规范排序）读取全部分片摘要。
     */
    public List<ManifestChunk> findChunks(long releaseId) {
        return jdbc.query("SELECT chunk_index, digest FROM release_manifest_chunk"
                        + " WHERE release_id = ? ORDER BY chunk_index",
                (rs, rowNum) -> new ManifestChunk(rs.getInt("chunk_index"), rs.getString("digest")),
                releaseId);
    }
}

package com.example.starter.firmware.repo;

import com.example.starter.firmware.domain.TaskAttempt;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

/**
 * 任务尝试代次数据访问。判定字段（verdict/verdict_reason/actual_aggregate/decided_at_utc）只在判定时写入一次。
 */
@Repository
public class AttemptRepository {

    private static final RowMapper<TaskAttempt> MAPPER = (rs, rowNum) -> new TaskAttempt(
            rs.getLong("id"), rs.getLong("task_id"), rs.getInt("attempt_no"),
            rs.getLong("release_id"), rs.getString("to_version"),
            rs.getString("expected_aggregate"), rs.getInt("required_count"), rs.getInt("received_count"),
            rs.getString("verdict"), rs.getString("verdict_reason"), rs.getString("actual_aggregate"),
            rs.getString("decided_at_utc"), rs.getString("created_at_utc"));

    private static final String COLUMNS = "id, task_id, attempt_no, release_id, to_version, expected_aggregate,"
            + " required_count, received_count, verdict, verdict_reason, actual_aggregate, decided_at_utc,"
            + " created_at_utc";

    private final JdbcTemplate jdbc;

    public AttemptRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void insert(long taskId, int attemptNo, long releaseId, String toVersion,
                       String expectedAggregate, int requiredCount, String createdAtUtc) {
        jdbc.update("INSERT INTO task_attempt (task_id, attempt_no, release_id, to_version,"
                        + " expected_aggregate, required_count, created_at_utc) VALUES (?, ?, ?, ?, ?, ?, ?)",
                taskId, attemptNo, releaseId, toVersion, expectedAggregate, requiredCount, createdAtUtc);
    }

    public Optional<TaskAttempt> find(long taskId, int attemptNo) {
        return jdbc.query("SELECT " + COLUMNS + " FROM task_attempt WHERE task_id = ? AND attempt_no = ?",
                MAPPER, taskId, attemptNo).stream().findFirst();
    }

    public List<TaskAttempt> findByTask(long taskId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM task_attempt WHERE task_id = ? ORDER BY attempt_no",
                MAPPER, taskId);
    }

    /**
     * 已接收分片数加一；调用方持有任务行锁。
     */
    public void incrementReceived(long taskId, int attemptNo) {
        jdbc.update("UPDATE task_attempt SET received_count = received_count + 1"
                + " WHERE task_id = ? AND attempt_no = ?", taskId, attemptNo);
    }

    /**
     * 固化判定结果；只在判定时调用一次，之后不改写。
     */
    public void decide(long taskId, int attemptNo, String verdict, String reason,
                       String actualAggregate, String decidedAtUtc) {
        jdbc.update("UPDATE task_attempt SET verdict = ?, verdict_reason = ?, actual_aggregate = ?,"
                        + " decided_at_utc = ? WHERE task_id = ? AND attempt_no = ?",
                verdict, reason, actualAggregate, decidedAtUtc, taskId, attemptNo);
    }
}

package com.example.starter.firmware.repo;

import com.example.starter.firmware.domain.ChunkReceipt;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.util.List;

/**
 * 分片接收证据数据访问。唯一约束 uk_receipt_task_attempt_chunk 保证同任务同代次同序号最多一笔。
 */
@Repository
public class ChunkReceiptRepository {

    private static final RowMapper<ChunkReceipt> MAPPER = (rs, rowNum) -> new ChunkReceipt(
            rs.getLong("id"), rs.getLong("task_id"), rs.getInt("attempt_no"), rs.getInt("chunk_index"),
            rs.getString("digest"), rs.getString("expected_digest"), rs.getBoolean("matched"),
            rs.getString("received_at_utc"));

    private static final String COLUMNS = "id, task_id, attempt_no, chunk_index, digest, expected_digest,"
            + " matched, received_at_utc";

    private final JdbcTemplate jdbc;

    public ChunkReceiptRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void insert(long taskId, int attemptNo, int chunkIndex, String digest,
                       String expectedDigest, boolean matched, String receivedAtUtc) {
        jdbc.update("INSERT INTO task_chunk_receipt (task_id, attempt_no, chunk_index, digest,"
                        + " expected_digest, matched, received_at_utc) VALUES (?, ?, ?, ?, ?, ?, ?)",
                taskId, attemptNo, chunkIndex, digest, expectedDigest, matched, receivedAtUtc);
    }

    public List<ChunkReceipt> findByAttempt(long taskId, int attemptNo) {
        return jdbc.query("SELECT " + COLUMNS + " FROM task_chunk_receipt"
                        + " WHERE task_id = ? AND attempt_no = ? ORDER BY chunk_index",
                MAPPER, taskId, attemptNo);
    }

    public List<ChunkReceipt> findByTask(long taskId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM task_chunk_receipt"
                        + " WHERE task_id = ? ORDER BY attempt_no, chunk_index", MAPPER, taskId);
    }
}

