        fingerprint = task.chunks|taskId|index:digest in submission order
        idempotency.execute(request.requestId(), "task.chunks", fingerprint, () -> {
            RolloutTask task = taskRepository.findByIdForUpdate(taskId) -> 404
            if (task.status() != PENDING) -> 409 TASK_NOT_RECEIVING (状态)
            ReleaseOrder order = releaseRepository.findById(task.releaseId()) -> 404 (should exist)
