                    // 不 increment received? received_count 表示已接收分片数。失败证据也算接收。increment。
                taskRepository.updateStatus(taskId, INTEGRITY_FAILED)
                attemptRepository.decide(..., "INTEGRITY_FAILED", failure, null, now)
                return view(INTEGRITY_FAILED)
            }
            // 全部合法：插入证据
            for chunk: insert receipt(matched=true); incrementReceived
